class Menu;
class MenuSystem;
class MenuEntry;

typedef bool MenuEntryButtonFunction( MenuEntry *entry, int buttonid );
typedef MenuEntryButtonFunction *pMenuEntryButtonFunction;

enum
{
	MENUCMD_NONE = 0,
	MENUCMD_SELECT,
	MENUCMD_START,
	MENUCMD_UP,
	MENUCMD_DOWN,
	MENUCMD_LEFT,
	MENUCMD_RIGHT,
	MENUCMD_CROSS,
	MENUCMD_TRIANGLE,
	MENUCMD_SQUARE,
	MENUCMD_CIRCLE,
	MENUCMD_L1,
	MENUCMD_R1,
	MENUCMD_L2,
	MENUCMD_R2
};

class MenuEntry
{
	unsigned int flags;

public:
	virtual ~MenuEntry();
	virtual int GetColor( void );
	virtual void Show( void );
	virtual void Hide( void );
	virtual void Enable( void );
	virtual void Disable( void );
	virtual void Activate( void );
	virtual void Deactivate( void );
	virtual void OnTick( float dtime ) {}
	virtual void OnMenuOpen( Menu *m, MenuSystem *c );
	virtual void OnMenuClose( void );
	virtual void OnButtonPress( int buttonid ) {}
	virtual void OnButtonRelease( int buttonid ) {}
	virtual void OnHide( void ) {}
	virtual void OnShow( void ) {}
	virtual void OnEnable( void ) {}
	virtual void OnDisable( void ) {}
	virtual void OnActivate( void ) {}
	virtual void OnDeactivate( void ) {}
	virtual int MenuText( char *text, int len ) { if (len>0) *text=0; return 0; }
};

class MenuEntryLabel : public MenuEntry
{
protected:
	const char *label;

public:
	virtual ~MenuEntryLabel();
	virtual int MenuText( char *text, int len );
};

class MenuEntryFunctionFloatEdit : public MenuEntryLabel
{
	float *tfloat;

protected:
	float lo, hi, step;
	char *format;
	pMenuEntryButtonFunction fn;

public:
	virtual ~MenuEntryFunctionFloatEdit();
	virtual void OnMenuOpen( Menu *m, MenuSystem *c );
	virtual int MenuText( char *text, int len );
	virtual void OnButtonPress( int buttonid );

	void FixValue( void );
	virtual void SetValue( float n ) { *tfloat = n; }
	virtual float GetValue( void ) { return tfloat ? *tfloat : 0; }
};

void MenuEntryFunctionFloatEdit::OnButtonPress( int buttonid )
{
  switch (buttonid)
  {
  case MENUCMD_LEFT:
	SetValue (GetValue () - step);
	FixValue ();
    break;
  case MENUCMD_RIGHT:
	SetValue (GetValue () + step);
	FixValue ();
    break;
  case MENUCMD_L1:
	SetValue (GetValue () - step * 10);
	FixValue ();
    break;
  case MENUCMD_R1:
	SetValue (GetValue () + step * 10);
	FixValue ();
    break;
  case MENUCMD_L2:
	SetValue (GetValue () - step * 100);
	FixValue ();
    break;
  case MENUCMD_R2:
	SetValue (GetValue () + step * 100);
	FixValue ();
    break;
	case MENUCMD_CROSS:
	if (fn) (*fn)(this,buttonid);
	break;
  default:
    MenuEntryLabel::OnButtonPress(buttonid);
  }
}
